<?php use App\Security\Gate; $q = ['type' => $type, 'value' => $value] + ($pid ? ['project' => $pid] : []); ?>
<h1>Reports</h1>
<form class="card filters" method="get"><div><label for="rt">Period</label><select id="rt" name="type"><option value="month"<?= $type === 'month' ? ' selected' : '' ?>>Month</option><option value="year"<?= $type === 'year' ? ' selected' : '' ?>>Year</option></select></div>
<div><label for="rv">Month (YYYY-MM) or year (YYYY)</label><input id="rv" name="value" value="<?= e($value) ?>" pattern="\d{4}(-\d{2})?"></div>
<div><label for="rp">Project</label><select id="rp" name="project"><option value=""><?= App\Security\Auth::isAdmin() ? 'All projects' : 'All my projects' ?></option><?php foreach ($projects as $p): ?><option value="<?= (int) $p['id'] ?>"<?= $pid === (int) $p['id'] ? ' selected' : '' ?>><?= e($p['name']) ?></option><?php endforeach; ?></select></div>
<div><button class="btn">Run report</button></div></form>
<p class="muted">Reporting period <?= e(fmt_date($period['from'])) ?> to <?= e(fmt_date($period['to'])) ?> · generated <?= e(local_dt(now_utc())) ?> · figures are actual records (no estimates or targets).</p>
<div class="grid grid-3"><div class="kpi"><div class="v"><?= e(minutes_to_hours($d['total_minutes'])) ?></div><div class="l">Approved volunteer hours</div></div>
<?php if (isset($d['applications'])): ?><div class="kpi"><div class="v"><?= (int) $d['applications']['received'] ?></div><div class="l">Applications received (<?= (int) $d['applications']['approved'] ?> approved, <?= (int) $d['applications']['rejected'] ?> rejected)</div></div>
<div class="kpi"><div class="v"><?= (int) $d['active_at_end'] ?></div><div class="l">Active volunteers at period end (<?= (int) $d['new_volunteers'] ?> new)</div></div><?php endif; ?></div>
<div class="card table-wrap"><h2 class="section-title">Hours by project</h2><?php if (!$d['hours']): ?><p class="empty">No approved hours in this period.</p><?php else: ?><table><thead><tr><th>Project</th><th>Volunteers</th><th>Hours</th></tr></thead><tbody><?php foreach ($d['hours'] as $h): ?><tr><td><?= e($h['project']) ?></td><td><?= (int) $h['volunteers'] ?></td><td><?= e(minutes_to_hours($h['minutes'])) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div>
<div class="card table-wrap"><h2 class="section-title">Activities and attendance</h2><?php if (!$d['activities']): ?><p class="empty">No activities in this period.</p><?php else: ?><table><thead><tr><th>Project</th><th>Activities</th><th>Completed</th><th>Cancelled</th><th>Attendance rate</th></tr></thead><tbody>
<?php foreach ($d['activities'] as $a): ?><tr><td><?= e($a['project']) ?></td><td><?= (int) $a['activities'] ?></td><td><?= (int) $a['completed'] ?></td><td><?= (int) $a['cancelled'] ?></td><td><?= (int) $a['rostered'] ? round(100 * $a['attended'] / $a['rostered'], 1) . '%' : '—' ?></td></tr><?php endforeach; ?></tbody></table>
<p class="hint">Attendance rate = present or late ÷ rostered, on completed activities.</p><?php endif; ?></div>
<?php if (!empty($d['skills'])): ?><div class="card"><h2 class="section-title">Skills of active volunteers</h2><ul><?php foreach ($d['skills'] as $s): ?><li><?= e($s['name']) ?>: <?= (int) $s['n'] ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if (Gate::allows('reports.export')): ?><div class="card"><h2 class="section-title">Exports (CSV, opens in Excel)</h2><p class="hint">Exports containing personal data are recorded in the audit log.</p><div class="actions">
<?php foreach (['projects' => 'Project summary', 'hours' => 'Approved hours (personal data)', 'attendance' => 'Attendance (personal data)'] as $k => $l): ?><a class="btn secondary" href="<?= e(url('/reports/export', $q + ['kind' => $k])) ?>"><?= e($l) ?></a><?php endforeach; ?></div></div><?php endif; ?>
